/*
 * dir_$copy_name_cross_page - copy an entry name from one directory page
 * to another through a 32-byte bounce buffer
 *
 * Original address: 0x00E4F034
 * Size: 204 bytes (0x00E4F034 .. 0x00E4F0FF)
 * Generated by: Claude Opus 5.5
 *
 * A nested Pascal procedure of dir_$add_entry, called only by its sibling
 * dir_$write_entry_to_page (0x00E4F274, five word arguments after a Pascal
 * result slot).  The directory handle is an uplevel value: `movea.l
 * (A6),A0' / `movea.l (A0),A0' / `movea.l (-0x4,A0),A2' reach the
 * grandparent's context pointer and `(0x8,A2)' is the handle; the
 * flattening passes it as the first argument.
 *
 * Frame: (0x8,A6) src_page, (0xA,A6) src_offset (D4), (0xC,A6) dest_page,
 * (0xE,A6) dest_offset (D6), (0x10,A6) byte_count (D3); A6-0x30 is the
 * 32-byte buffer, D2 the bytes done.
 *
 * Blocks (one pass per 32-byte chunk, done = 0 first):
 *   0x00E4F05C-0x00E4F07A  map src_page; source = page + done + src_offset
 *   0x00E4F07C-0x00E4F092  chunk = byte_count - done, at most 0x20 (the
 *                          comparison is on the sign-extended longwords)
 *   0x00E4F096-0x00E4F0B4  copy chunk bytes into the buffer (1-based loop,
 *                          `subq.w' / `bcc')
 *   0x00E4F0B6-0x00E4F0EA  map dest_page (which may evict the source
 *                          mapping); copy the buffer to page + done +
 *                          dest_offset
 *   0x00E4F0EC-0x00E4F0F2  done += chunk; repeat while done < byte_count
 */

#include "dir/dir_internal.h"

#define DIR_COPY_CHUNK  0x20    /* `moveq #0x20,D7' 0x00E4F07E */

void dir_$copy_name_cross_page(uint32_t handle, int16_t src_page,
                               int16_t src_offset, int16_t dest_page,
                               int16_t dest_offset, int16_t byte_count)
{
    uint8_t buf[DIR_COPY_CHUNK];        /* A6-0x30 */
    int16_t done = 0;                   /* D2 */
    int16_t chunk;                      /* A6-0x38 */
    int16_t i;                          /* D0 */
    uint8_t *p;                         /* A0 */

    do {
        /* 0x00E4F05C-0x00E4F07A */
        p = (uint8_t *)dir_$map_page(ARCH_VA_TO_PTR(handle), src_page);
        p = p + (int32_t)done + (int32_t)src_offset;

        /* 0x00E4F07C-0x00E4F092 */
        if ((int32_t)byte_count - (int32_t)done > DIR_COPY_CHUNK) {
            chunk = DIR_COPY_CHUNK;
        } else {
            chunk = (int16_t)(byte_count - done);
        }

        /* 0x00E4F096-0x00E4F0B4 */
        for (i = 1; i <= chunk; i++) {
            buf[i - 1] = p[i - 1];
        }

        /* 0x00E4F0B6-0x00E4F0EA */
        p = (uint8_t *)dir_$map_page(ARCH_VA_TO_PTR(handle), dest_page);
        p = p + (int32_t)done + (int32_t)dest_offset;
        for (i = 1; i <= chunk; i++) {
            p[i - 1] = buf[i - 1];
        }

        /* 0x00E4F0EC-0x00E4F0F2 */
        done = (int16_t)(done + chunk);
    } while (done < byte_count);
}
